import { describe, expect, it } from "vitest";
import { buildTemplatePreviewPath } from "./startTemplatePreview.js";
describe("buildTemplatePreviewPath", () => {
    it("builds the template preview path for a simple key", () => {
        expect(buildTemplatePreviewPath("my-fn")).toBe("/plugin/trace-functions/my-fn/template-preview");
    });
    it("URL-encodes function keys with reserved characters", () => {
        expect(buildTemplatePreviewPath("scope/sub key")).toBe("/plugin/trace-functions/scope%2Fsub%20key/template-preview");
    });
    it("adds the organization handoff ticket to the preview path", () => {
        expect(buildTemplatePreviewPath("scope/sub key", "ticket/id")).toBe("/plugin/trace-functions/scope%2Fsub%20key/template-preview?ticket=ticket%2Fid");
    });
});
